import re

def solve(env, goal):
    def norm(text):
        return re.sub(r'\s+\d+$', '', text.strip(), flags=re.I)

    def parse_goal(g):
        g = g.lower()
        m = re.search(r'cool (?:some |a |an |the )?(.+?) and (?:put|place) (?:it )?(?:in|on|into|to) (?:a |an |the )?(.+?)(?:\.|$)', g)
        if m:
            return norm(m.group(1)), norm(m.group(2))
        m = re.search(r'(?:put|place) (?:a |an |the )?(?:cooled )?(.+?) (?:in|on|into|to) (?:a |an |the )?(.+?)(?:\.|$)', g)
        if m:
            return norm(m.group(1)), norm(m.group(2))
        m = re.search(r'cool (?:some |a |an |the )?(.+?)(?:\.|$)', g)
        if m:
            return norm(m.group(1)), None
        return None, None

    obj_type, dest_type = parse_goal(goal)
    if obj_type is None:
        return

    def inventory():
        env.step("inventory")
        return env.observation.lower()

    def has_object(otype):
        inv = inventory()
        return re.search(r'\b' + re.escape(otype.lower()) + r' \d+', inv) is not None

    def visible_list():
        obs = env.observation
        m = re.search(r'(?:you see|in it, you see|on it, you see|on the .+?, you see)\s*(.*?)(?:\.|$)', obs, re.I)
        if not m:
            return []
        items = m.group(1)
        found = []
        for part in re.split(r',| and ', items):
            part = part.strip()
            mm = re.match(r'(?:a |an |the )?(.+? \d+)$', part, re.I)
            if mm:
                found.append(mm.group(1).strip())
        return found

    def find_object(otype):
        if has_object(otype):
            return True
        # inspect current location first
        items = visible_list()
        for it in items:
            if norm(it).lower() == otype.lower():
                env.step("take %s" % it)
                if has_object(otype):
                    return True
        # explore receptacles
        env.step("look")
        obs = env.observation
        receps = re.findall(r'\b((?:cabinet|drawer|fridge|microwave|sinkbasin|garbagecan|countertop|diningtable|stoveburner|toaster|coffeemachine|safe|desk|shelf|table|bed|sofa|armchair|bathtub|toilet|shower|oven|dishwasher)\s+\d+)', obs, re.I)
        seen = []
        for r in receps:
            if r.lower() in seen:
                continue
            seen.append(r.lower())
            env.step("go to %s" % r)
            if "closed" in env.observation.lower():
                env.step("open %s" % r)
            items = visible_list()
            for it in items:
                if norm(it).lower() == otype.lower():
                    env.step("take %s" % it)
                    if has_object(otype):
                        return True
        return False

    def find_destination(dtype):
        env.step("look")
        obs = env.observation
        receps = re.findall(r'\b((?:cabinet|drawer|fridge|microwave|sinkbasin|garbagecan|countertop|diningtable|stoveburner|toaster|coffeemachine|safe|desk|shelf|table|bed|sofa|armchair|bathtub|toilet|shower|oven|dishwasher)\s+\d+)', obs, re.I)
        for r in receps:
            if norm(r).lower() == dtype.lower():
                return r
        # maybe not visible yet; navigate and re-look
        for r in receps:
            env.step("go to %s" % r)
            env.step("look")
            obs = env.observation
            receps2 = re.findall(r'\b((?:cabinet|drawer|fridge|microwave|sinkbasin|garbagecan|countertop|diningtable|stoveburner|toaster|coffeemachine|safe|desk|shelf|table|bed|sofa|armchair|bathtub|toilet|shower|oven|dishwasher)\s+\d+)', obs, re.I)
            for r2 in receps2:
                if norm(r2).lower() == dtype.lower():
                    return r2
        return None

    def find_fridge():
        env.step("look")
        obs = env.observation
        receps = re.findall(r'\b((?:cabinet|drawer|fridge|microwave|sinkbasin|garbagecan|countertop|diningtable|stoveburner|toaster|coffeemachine|safe|desk|shelf|table|bed|sofa|armchair|bathtub|toilet|shower|oven|dishwasher)\s+\d+)', obs, re.I)
        for r in receps:
            if norm(r).lower() == "fridge":
                return r
        return None

    if not find_object(obj_type):
        return

    fridge = find_fridge()
    if fridge is None:
        return
    env.step("go to %s" % fridge)
    if "closed" in env.observation.lower():
        env.step("open %s" % fridge)

    inv = inventory()
    m = re.search(re.escape(obj_type.lower()) + r' \d+', inv)
    if not m:
        return
    obj = m.group(0)
    env.step("cool %s with %s" % (obj, fridge))

    dest = find_destination(dest_type)
    if dest is None:
        return
    env.step("go to %s" % dest)
    env.step("move %s to %s" % (obj, dest))
